    """Memory system: label-aware profile-based retrieval."""

    def __init__(self, llm):
        super().__init__(llm)
        self.examples = []          # {"input", "target"}
        self.labels = []            # labels in order of first appearance
        self.label_profiles = defaultdict(Counter)  # label -> token frequency distribution
        self.confusions = Counter() # (predicted, gold) -> count, learned from online mistakes
        self.words = defaultdict(Counter)

    # ---------------------------------------------------------------- learning
    def learn_from_batch(self, batch_results):
        for r in batch_results:
            gold = _norm(r["ground_truth"])
            ok = bool(r.get("was_correct", True))
            if gold not in self.labels:
                self.labels.append(gold)

            # Update label profile with tokens from this example
            toks = _toks(r["input"])
            self.label_profiles[gold].update(toks)

            if not ok:
                self.confusions[(_norm(r.get("prediction")), gold)] += 1
            if CONFIG["notes"]:
                self.words[gold].update(toks)
            if CONFIG["learn"] == "errors_only" and ok and any(e["target"] == gold for e in self.examples):
                continue
            ex = {"input": r["input"], "target": gold, "hard": not ok}
            if CONFIG["store"] == "per_label_cap":
                same = [e for e in self.examples if e["target"] == gold]
                if len(same) >= CONFIG["cap"]:
                    self.examples.remove(same[0])
            self.examples.append(ex)
        if CONFIG["store"] == "errors_first":
            self.examples.sort(key=lambda e: not e.get("hard", False))

    # --------------------------------------------------------------- retrieval
    def _similar(self, query: str):
        q = _toks(query)
        scored = []
        for i, e in enumerate(self.examples):
            t = _toks(e["input"])
            sim = len(q & t) / max(1, len(q | t))
            scored.append((sim, i, e))
        scored.sort(key=lambda x: (-x[0], -x[1]))
        return [e for _, _, e in scored]

    def _label_profile_score(self, query_toks: set, label: str) -> float:
        """Score a label by how well its learned profile matches the query tokens."""
        if label not in self.label_profiles:
            return 0.0
        profile = self.label_profiles[label]
        # Count overlap between query and label's typical tokens
        overlap = sum(profile[t] for t in query_toks)
        total = sum(profile.values()) if profile else 1
        return overlap / max(1.0, total)

    def _select(self, query: str):
        sel, k = CONFIG["select"], CONFIG["k"]
        if sel == "all":
            chosen = list(self.examples)
        elif sel == "recent":
            chosen = self.examples[-k:]
        else:
            ranked = self._similar(query)
            chosen = ranked[:k]

            if sel == "label_profile":
                # NEW: Route retrieval through label semantic profiles
                q = _toks(query)

                # Score labels by profile similarity to query
                label_scores = {}
                for lab in self.labels:
                    label_scores[lab] = self._label_profile_score(q, lab)

                # Retrieve top-k examples from high-scoring labels
                high_scoring_labels = sorted(label_scores.items(), key=lambda x: -x[1])[:5]
                high_scoring_label_set = {lab for lab, score in high_scoring_labels if score > 0}

                # Prioritize examples of high-scoring labels, then examples of other labels
                chosen_from_profile = [e for e in ranked if e["target"] in high_scoring_label_set]
                chosen_from_other = [e for e in ranked if e["target"] not in high_scoring_label_set]
                chosen = chosen_from_profile + chosen_from_other
                chosen = chosen[:k]

                # Add contrastive examples of confusing rivals (using confusion matrix)
                top = [e["target"] for e in chosen[:3]]
                rivals = []
                for (p, g), n in self.confusions.most_common():
                    if p in top and g not in top:
